/* The beta's sparse unicode map is: '-' (45), '0'..'9' (48..57),
 * ':' (58). Retain the original glyph table indices (0 is sentinel).
 */
static int sleep_glyph_id(uint32_t code){
    if(code=='-')return 1;
    if(code>='0'&&code<='9')return (int)(code-'0')+2;
    if(code==':')return 12;
    return 0;
}
static bool sleep_get_dsc(const lv_font_t *font,lv_font_glyph_dsc_t *out,
                         uint32_t letter,uint32_t following){
    (void)following;
    const int id=sleep_glyph_id(letter);
    if(!id)return false;
    const mira_sleep_glyph_t *g=&glyph_dsc[id];
    out->resolved_font=font;
    out->gid.index=(uint32_t)id;
    out->format=LV_FONT_GLYPH_FORMAT_A4;
    out->adv_w=(g->adv_w+8u)>>4;
    out->box_w=g->box_w;
    out->box_h=g->box_h;
    out->ofs_x=g->ofs_x;
    out->ofs_y=g->ofs_y;
    out->stride=0;
    out->is_placeholder=0;
    return true;
}
static const void *sleep_get_bitmap(lv_font_glyph_dsc_t *dsc,lv_draw_buf_t *draw_buf){
    if(!dsc||dsc->gid.index<1||dsc->gid.index>=13)return NULL;
    const mira_sleep_glyph_t *g=&glyph_dsc[dsc->gid.index];
    const uint8_t *packed=glyph_bitmap+g->bitmap_index;
    if(dsc->req_raw_bitmap)return packed;
    if(!draw_buf||!draw_buf->data)return NULL;
    const uint32_t stride=lv_draw_buf_width_to_stride(g->box_w,LV_COLOR_FORMAT_A8);
    uint8_t *out=(uint8_t *)draw_buf->data;
    for(uint32_t y=0;y<g->box_h;y++){
        for(uint32_t x=0;x<g->box_w;x++){
            const uint32_t k=y*(uint32_t)g->box_w+x;
            const uint8_t pair=packed[k>>1];
            out[y*stride+x]=(uint8_t)(((k&1u)?(pair&15u):(pair>>4))*17u);
        }
    }
    lv_draw_buf_flush_cache(draw_buf,NULL);
    return draw_buf;
}
const lv_font_t mira_sleep_montserrat_120={
    .fallback=&lv_font_montserrat_48,
    .get_glyph_dsc=sleep_get_dsc,.get_glyph_bitmap=sleep_get_bitmap,
    .line_height=148,.base_line=31,
    .subpx=LV_FONT_SUBPX_NONE,.kerning=LV_FONT_KERNING_NONE,
    .static_bitmap=1,.underline_position=-4,.underline_thickness=2
};
